with zipfile.ZipFile(io.BytesIO(base64.b64decode("".join(SRC)))) as z:
    z.extractall(PROJ)
print("project:", sorted(os.listdir(PROJ)), flush=True)

subprocess.run([sys.executable, "-m", "pip", "install", "-q", "gymnasium"],
               check=False, timeout=240)
try:
    import gymnasium
    print("gymnasium available:", gymnasium.__version__, flush=True)
except Exception as exc:
    print("gymnasium unavailable (standalone API fallback):", exc, flush=True)

r = subprocess.run([sys.executable, "main.py"], cwd=PROJ, capture_output=True, text=True)
sys.stdout.write(r.stdout[-16000:])
if r.stderr:
    sys.stderr.write("STDERR TAIL:\n" + r.stderr[-4000:])
print(f"\nMAIN_EXIT_CODE={r.returncode}", flush=True)
sys.exit(r.returncode)
